#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Trial: does the logging_simulator replay accept a route (AD API set_route_points) so that planning and control run for
# real (trajectory, control_cmd)? Plain ros2 (no FISH), rviz off, bag at RATE, goal from sim_route_tool.py (route.json).
# usage: route_trial.sh <route.json> [log_dir]      env: IMG (fishwait29), RATE (0.5), GOAL_AT (seconds after replay start, 8)
set -u; R=${1:?route.json}; LD=${2:-$HOME/fish_traces/sim_route/trial_$(date +%H%M%S)}; mkdir -p "$LD"
IMG=${IMG:-autoware-dev-trt-a1000-fishwait29:latest}; RATE=${RATE:-0.5}; GOAL_AT=${GOAL_AT:-8}
SET_ROUTE=$(python3 -c "import json; print(json.load(open('$R'))['adapi']['set_route_points'])")
cp "$R" "$LD/route.json"; echo "$SET_ROUTE" > "$LD/set_route.cmd"
NAME=route_trial_$$; docker rm -f $NAME >/dev/null 2>&1
docker run -d --name $NAME --gpus all --privileged --net host -e RATE=$RATE -e GOAL_AT=$GOAL_AT -v "$LD":/trial "$IMG" bash -lc '
  set +u; source /opt/ros/humble/setup.bash; source /opt/autoware/setup.bash; export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp
  unset CYCLONEDDS_URI; export FISH_ENABLED=0
  R2=/opt/ros/humble/bin/ros2
  ( $R2 launch autoware_launch logging_simulator.launch.xml map_path:=/root/autoware_map/sample-map-rosbag vehicle_model:=sample_vehicle sensor_model:=sample_sensor_kit rviz:=false > /trial/launch.log 2>&1 ) &
  LPID=$!
  for i in $(seq 1 90); do $R2 service list 2>/dev/null | grep -q /api/routing/set_route_points && break; sleep 5; done
  echo "[trial] $(date +%T) adapi up after $((i*5)) s; nodes: $($R2 node list 2>/dev/null | wc -l)" | tee -a /trial/trial.log
  sleep 20
  ( $R2 bag play /root/autoware_map/sample-rosbag -r $RATE -s sqlite3 > /trial/replay.log 2>&1 ) & BPID=$!
  echo "[trial] $(date +%T) replay started (rate $RATE)" | tee -a /trial/trial.log
  for i in $(seq 1 20); do st=$(timeout 8 $R2 topic echo --once /api/localization/initialization_state 2>/dev/null | grep "^state" | head -1); echo "[trial] $(date +%T) localization init state: $st" | tee -a /trial/trial.log; [[ "$st" == *"3"* ]] && break; sleep 3; done
  timeout 6 $R2 topic echo --once /localization/kinematic_state --no-arr 2>/dev/null | grep -A3 "position:" | head -4 | tee -a /trial/trial.log
  sleep $GOAL_AT
  echo "[trial] $(date +%T) set_route_points" | tee -a /trial/trial.log
  out=$(timeout 40 bash -c "$(cat /trial/set_route.cmd)" 2>&1 | tail -4); echo "$out" | tee -a /trial/trial.log
  ( timeout 90 $R2 topic hz /planning/scenario_planning/trajectory > /trial/hz_traj.log 2>&1 ) & ( timeout 90 $R2 topic hz /control/command/control_cmd > /trial/hz_ctrl.log 2>&1 ) &
  ( timeout 90 $R2 topic echo /planning/scenario_planning/trajectory --no-arr --field header.stamp 2>/dev/null | grep -c sec > /trial/n_traj.txt ) &
  for i in 1 2 3 4; do
    st=$(timeout 8 $R2 topic echo --once /api/routing/state 2>/dev/null | grep "^state" | head -1); echo "[trial] $(date +%T) routing state: $st" | tee -a /trial/trial.log
    echo "[trial] trajectory hz: $(timeout 8 $R2 topic hz /planning/scenario_planning/trajectory 2>&1 | grep -m1 average)" | tee -a /trial/trial.log
    echo "[trial] control_cmd hz: $(timeout 8 $R2 topic hz /control/command/control_cmd 2>&1 | grep -m1 average)" | tee -a /trial/trial.log
    echo "[trial] gate control_cmd hz: $(timeout 8 $R2 topic hz /control/trajectory_follower/control_cmd 2>&1 | grep -m1 average)" | tee -a /trial/trial.log
    [ $i = 2 ] && { out=$(timeout 30 $R2 service call /api/operation_mode/change_to_autonomous autoware_adapi_v1_msgs/srv/ChangeOperationMode "{}" 2>&1 | tail -2); echo "[trial] change_to_autonomous: $out" | tee -a /trial/trial.log; }
  done
  echo "[trial] $(date +%T) operation mode: $(timeout 8 $R2 topic echo --once /api/operation_mode/state 2>/dev/null | grep -E "^mode|^is_autonomous" | tr "\n" " ")" | tee -a /trial/trial.log
  wait $BPID 2>/dev/null; echo "[trial] $(date +%T) replay ended" | tee -a /trial/trial.log
  sleep 3; echo "[trial] trajectory: $(grep -c average /trial/hz_traj.log) hz samples, last: $(grep average /trial/hz_traj.log | tail -1); control_cmd: $(grep -c average /trial/hz_ctrl.log) samples, last: $(grep average /trial/hz_ctrl.log | tail -1)" | tee -a /trial/trial.log
  kill -INT $LPID 2>/dev/null; sleep 10; pkill -INT -f component_container 2>/dev/null; sleep 5
  echo "[trial] TRIAL DONE" | tee -a /trial/trial.log
' >/dev/null || { echo "cannot start container"; exit 2; }
echo "trial container $NAME started; log $LD/trial.log"
